"""Normalize release records at the input boundary."""


class JournalError(ValueError):
    pass


def _is_id(value):
    return isinstance(value, str) and value != ""


def _read_dependencies(row):
    depends_on = row.get("depends_on", [])
    if not isinstance(depends_on, list):
        raise JournalError("invalid-change")
    for dep in depends_on:
        if not _is_id(dep):
            raise JournalError("invalid-change")
    return frozenset(depends_on)


def read_changes(records):
    """Validate and deduplicate change records.

    Identical duplicates (same id, component, units and dependency set) collapse
    to one record; conflicting reuse of an ID fails with ``conflicting-change``.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = {}
    for row in records:
        if (not isinstance(row, dict) or not _is_id(row.get("id"))
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        change = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": _read_dependencies(row),
        }
        existing = changes.get(change["id"])
        if existing is None:
            changes[change["id"]] = change
        elif existing != change:
            raise JournalError("conflicting-change")
    return list(changes.values())


def read_applied(value):
    """Normalize the persisted release journal to a set of change IDs."""
    if value is None:
        return set()
    if not isinstance(value, list):
        raise JournalError("invalid-change")
    applied = set()
    for entry in value:
        if not _is_id(entry):
            raise JournalError("invalid-change")
        applied.add(entry)
    return applied


def read_retain(value):
    """Normalize the rollback ``retain`` list to an ordered list of change IDs."""
    if value is None:
        return []
    if not isinstance(value, list):
        raise JournalError("invalid-retain")
    retain = []
    for entry in value:
        if not _is_id(entry) or entry in retain:
            raise JournalError("invalid-retain")
        retain.append(entry)
    return retain

