"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes, read_retain
from policy import PolicyError, plan_limit, validate


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def units_of(rows):
    return sum(row["units"] for row in rows)


def success(rows):
    return {"status": "ok", "actions": [row["id"] for row in rows], "units": units_of(rows)}


def ordered(changes):
    """Full deterministic topological order with lexicographic tie-breaking.

    Only ready changes compete: an ID becomes eligible once every dependency is
    placed. The order is computed over all changes, applied or not, so replay
    does not change it.
    """
    by_id = {row["id"]: row for row in changes}
    indegree = {change_id: 0 for change_id in by_id}
    dependents = {change_id: [] for change_id in by_id}
    for change_id, row in by_id.items():
        for dep in row["depends_on"]:
            if dep not in by_id:
                raise JournalError("unknown-dependency")
            indegree[change_id] += 1
            dependents[dep].append(change_id)
    ready = [change_id for change_id, count in indegree.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(by_id[change_id])
        for child in dependents[change_id]:
            indegree[child] -= 1
            if indegree[child] == 0:
                heapq.heappush(ready, child)
    if len(order) != len(by_id):
        raise JournalError("dependency-cycle")
    return order


def required_by(by_id, retained, applied):
    """Applied changes the retained changes need, directly or transitively."""
    required = set(retained)
    stack = list(retained)
    while stack:
        for dep in by_id[stack.pop()]["depends_on"]:
            if dep in applied and dep not in required:
                required.add(dep)
                stack.append(dep)
    return required


def rollback_actions(order, applied, retain):
    """Reverse the applied changes, holding back the retained closure.

    Returns ``None`` when ``retain`` names a change that is not applied.
    """
    by_id = {row["id"]: row for row in order}
    if any(change_id not in applied for change_id in retain):
        return None
    held = required_by(by_id, retain, applied)
    return [row for row in reversed(order)
            if row["id"] in applied and row["id"] not in held]


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = validate(request)
        if request["action"] == "rollback":
            retain = read_retain(request.get("retain"))
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied"))
        order = ordered(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    if request["action"] == "rollback":
        if applied - {row["id"] for row in changes}:
            return failure("unknown-dependency")
        actions = rollback_actions(order, applied, retain)
        if actions is None:
            return failure("invalid-retain")
        return success(actions)
    if applied - {row["id"] for row in changes}:
        return failure("unknown-dependency")
    actions = [row for row in order if row["id"] not in applied]
    if units_of(actions) > plan_limit(budget):
        return failure("budget-exceeded")
    return success(actions)

policy.py.text:
"""Validate release policy before computing actions."""

ENVIRONMENTS = {"staging", "production"}
ACTIONS = {"plan", "rollback"}

# A staging plan may use at most this many units, whatever the request allows.
STAGING_PLAN_CEILING = 3


class PolicyError(ValueError):
    pass


def validate(request):
    """Validate environment, action and budget, in this order.

    Environment and action are checked against the transport contract, so an
    unknown environment or action is reported before the production freeze.
    """
    environment = request.get("environment")
    if environment not in ENVIRONMENTS:
        raise PolicyError("invalid-environment")
    if request.get("action") not in ACTIONS:
        raise PolicyError("unsupported-action")
    budget = request.get("budget")
    if type(budget) is not int or budget < 0:
        raise PolicyError("invalid-budget")
    if environment == "production":
        raise PolicyError("production-frozen")
    return budget


def plan_limit(request_budget):
    """Effective plan budget: the smaller of the request budget and the ceiling."""
    return min(request_budget, STAGING_PLAN_CEILING)

