"""Compose policy and journal data into a plan.

Planner owns everything that needs the whole change set at once: graph
validation, cycle detection, the deterministic topological order, replay of the
persisted journal, and budget accounting. It also assembles the success/failure
envelopes so that no other module can emit a partial result.
"""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _topological_order(changes):
    """Return all change IDs in a deterministic dependency order.

    Ordering rule: repeatedly take the lexicographically smallest ID among the
    changes whose dependencies are all already placed. Kahn's algorithm with a
    heap implements exactly that rule.

    Why a heap and not "sort IDs once": sorting the full ID list would let a
    large-but-eligible ID run ahead of a small-but-blocked one (e.g. `a` depends
    on `c`: the sorted order `a,b,c` is invalid). The tie-break must be applied
    to the *currently eligible* set at every step.

    A prerequisite (a dependency ID that is not itself a change) is treated as
    already satisfied: G1 lets `applied` name changes that are no longer in
    `changes` (a component retired after release), and a retired prerequisite
    must not resurrect as a phantom node in the plan.
    """
    by_id = {row["id"]: row for row in changes}
    dependents = {change_id: [] for change_id in by_id}
    pending = {}

    for row in changes:
        change_id = row["id"]
        blockers = {dep for dep in row["deps"] if dep in by_id}
        pending[change_id] = len(blockers)
        for dep in blockers:
            dependents[dep].append(change_id)

    ready = [change_id for change_id in by_id if pending[change_id] == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in dependents[change_id]:
            pending[dependent] -= 1
            if pending[dependent] == 0:
                heapq.heappush(ready, dependent)

    # Anything left unplaced is stuck behind a cycle. Ordering always covers the
    # full graph (before replay filtering), so a cycle inside an already applied
    # branch still fails the request instead of being silently skipped.
    if len(order) != len(by_id):
        raise JournalError("dependency-cycle")
    return order


def _select(action, order, applied, changes):
    """Choose which changes to emit, in execution order.

    `plan` emits the not-yet-applied changes in topological order; applied
    entries stay in the order (they satisfy dependencies) but contribute no
    budget. `rollback` must undo them: it emits every applied change in the
    reverse of the *full* order, so a dependency is always undone after the
    changes that relied on it. Building the rollback order from only the applied
    subset would produce a different order whenever applied entries are
    interleaved with unapplied ones.
    """
    if action == "rollback":
        return [change_id for change_id in reversed(order) if change_id in applied]
    # Emitted only when it is part of this request: a journal entry that names
    # an ID absent from `changes` has nothing to emit.
    return [change_id for change_id in order
            if change_id not in applied and change_id in changes]


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []))
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    by_id = {row["id"]: row for row in changes}
    # Replay is checked before ordering: a journal naming a change that is not
    # in `changes` is contradictory input (`unknown-dependency`), and resolving
    # it first keeps the error independent of whether a cycle also exists.
    unknown = sorted(applied - by_id.keys())
    if unknown:
        return failure("unknown-dependency")
    # Already known to be released: supplied by `changes` or by the journal.
    # A prerequisite may be an `applied` ID that is absent from `changes` (a
    # component retired after release); it still satisfies the dependency.
    released = by_id.keys() | applied
    for change_id in sorted(by_id):
        missing = sorted(dep for dep in by_id[change_id]["deps"] if dep not in released)
        if missing:
            return failure("unknown-dependency")

    try:
        order = _topological_order(changes)
    except JournalError as exc:
        return failure(str(exc))

    action = request["action"]
    actions = _select(action, order, applied, by_id)
    units = sum(by_id[change_id]["units"] for change_id in actions)
    # `rollback` is exempt: shrinking a release is the recovery path and must
    # not be blocked by the remaining plan budget. Its budget is still
    # validated above.
    if action == "plan" and units > budget:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": actions, "units": units}

