    成立条件：变更 ID 已由 journal 去重且唯一；依赖集合已规范化。
    反例提醒：不能先整体排序再逐个输出——那会在“先小字母但暂不可进入”的
    节点上过早阻塞，导致序次不确定。
    """
    by_id = {change["id"]: change for change in changes}
    indegree = {}
    dependents = {change["id"]: [] for change in changes}
    for change in changes:
        deps = set(change["depends_on"])
        # 依赖指向未声明的变更：无法判断何时才可执行，宁拒不错序。
        missing = sorted(dep for dep in deps if dep not in by_id)
        if missing:
            raise JournalError("unknown-dependency")
        indegree[change["id"]] = len(deps)
        for dep in deps:
            dependents[dep].append(change["id"])
    ready = [change_id for change_id, count in indegree.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        current = heapq.heappop(ready)
        order.append(current)
        for follower in dependents[current]:
            indegree[follower] -= 1
            # 仅在入度归零时推进，保证每个变更都在其全部依赖之后才被入选。
            if indegree[follower] == 0:
                heapq.heappush(ready, follower)
    if len(order) != len(changes):
        # 有环：环上节点入度永远不归零；环可能在未应用部分，故对全图检测。
        raise JournalError("dependency-cycle")
    return order


def retained_closure(retain, by_id, applied_set):
    """计算 G2 保留闭包：retain 自身 + 在 applied 集合内沿 depends_on 传递可达的依赖。

    为什么要限制在 applied 集合内：回滚只处理已应用项，未应用的依赖无法被“保留”。
    若保留集合里出现非已应用 ID，它既不会出现在回滚输出里也不会消耗配额，
    所以把边界固定在已应用集合上，闭包与回滚动作集合语义才一致。

    成立条件：拓扑序已确认无环，因此这里的可达遍历必然终止（但仍用显式 visited
    防御重复入栈，避免同一依赖被多次展开）。
    注意：这不是简单取与 retain 相关的全部依赖，而是按“逆全序发出”时需要同时保留的
    对象——先发生（更靠前）的依赖必须在保留时一起留下，否则回滚会拆掉仍在用的基础件。
    """
    kept = set()
    stack = []
    for change_id in retain:
        if change_id not in kept:
            kept.add(change_id)
            stack.append(change_id)
    while stack:
        current = stack.pop()
        for dep in by_id[current]["depends_on"]:
            if dep in applied_set and dep not in kept:
                kept.add(dep)
                stack.append(dep)
    return kept


def _emit(change_ids, by_id):
    """组装成功结果；units 等于实际发出动作的单位总和（已应用项不计）。"""
    return {
        "status": "ok",
        "actions": list(change_ids),
        "units": sum(by_id[change_id]["units"] for change_id in change_ids),
    }


def plan(request):
    """校验整单并按 action 计算动作集合。

    判定次序：请求形状 → 策略（环境→生产冻结→动作→预算数值）→ journal（变更/日志）→ 图
    → （仅 staging rollback）`retain` → 配额。该次序保持既有错误码优先级不变
    （坏环境先于坏 changes，生产冻结先于图与变更记录），并满足 CHANGE-G2：
    冻结在任何 changes/图读取之前返回，不给部分动作。

    预算只有一个口径：`budget` 是 policy 返回的“有效值”（staging plan 已取 min(…, 3)），
    本函数不再对原始 request budget 取值、也不再取 min，避免两处口径分叉。
    """
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        action, budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request, changes)
        order = topological_order(changes)
        # retain 仅在 staging rollback 上生效：plan 即使携带 retain 也必须忽略。
        # 放在图校验之后，是为了让 G1 已有的图错误码（unknown-dependency/
        # dependency-cycle）继续优先于无效的 retain 报告；此时 applied 已确认均属本批。
        retain = read_retain(request, applied) if action == "rollback" else []
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    by_id = {change["id"]: change for change in changes}
    if action == "rollback":
        # 回滚语义：逆全序撤销，但只退已应用项；依赖尚未应用的变更绝不能回滚。
        # 预算已由 policy 校验但按 SPEC 不封顶回滚，因此这里不再做 budget-exceeded 判定。
        applied_set = set(applied)
        skipped = retained_closure(retain, by_id, applied_set)
        emitted = [
            change_id
            for change_id in reversed(order)
            if change_id in applied_set and change_id not in skipped
        ]
        return _emit(emitted, by_id)
    # plan：只发未应用项；已应用项已满足依赖且不占预算，所以预算只对发出项合计校验。
    applied_set = set(applied)
    emitted = [change_id for change_id in order if change_id not in applied_set]
    units = sum(by_id[change_id]["units"] for change_id in emitted)
    if units > budget:
        # 配额拒绝必须整体失败：不发任何部分动作（actions 为空、units 为 0）。
        return failure("budget-exceeded")
    return _emit(emitted, by_id)

