"""Compose policy and journal data into a release plan."""
import heapq

from journal import JournalError, read_applied, read_changes, read_retain
from policy import FROZEN_ERROR, PolicyError, caps, effective_budget, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def validate_graph(changes, applied, retain=()):
    """Reject unknown IDs then cycles, as that precedence has always held."""
    known = {row["id"] for row in changes}
    for row in changes:
        for dependency in row["depends_on"]:
            if dependency not in known:
                raise JournalError("unknown-dependency")
    for stale in applied:
        if stale not in known:
            raise JournalError("unknown-dependency")
    for change_id in retain:
        if change_id not in applied:
            raise JournalError("invalid-retain")
    order = ordered_ids(changes)
    if len(order) != len(changes):
        raise JournalError("dependency-cycle")
    return order


def ordered_ids(changes):
    """Deterministic topological order with lexicographic tie-breaking."""
    by_id = {row["id"]: row for row in changes}
    waiting = {change_id: len(row["depends_on"]) for change_id, row in by_id.items()}
    dependents = {change_id: [] for change_id in by_id}
    for row in changes:
        for dependency in row["depends_on"]:
            dependents[dependency].append(row["id"])
    ready = [change_id for change_id, count in waiting.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in dependents[change_id]:
            waiting[dependent] -= 1
            if waiting[dependent] == 0:
                heapq.heappush(ready, dependent)
    return order


def retained_ids(by_id, applied, retain):
    """Return ``retain`` plus its transitive applied dependencies.

    An applied change can only be retained if what it depends on stays too;
    dependencies outside ``applied`` were never applied, so they cannot be
    retained and impose nothing on the rollback.
    """
    kept = set()
    pending = list(retain)
    while pending:
        change_id = pending.pop()
        if change_id in kept or change_id not in applied:
            continue
        kept.add(change_id)
        pending.extend(by_id[change_id]["depends_on"])
    return kept


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
