"""Normalize release records and replay state at the input boundary."""


class JournalError(ValueError):
    pass


def _ids(value, error="invalid-change"):
    """Return a deduplicated list of change IDs, or raise ``error``."""
    if not isinstance(value, list):
        raise JournalError(error)
    seen = []
    for item in value:
        if not isinstance(item, str) or not item:
            raise JournalError(error)
        if item not in seen:
            seen.append(item)
    return seen


def read_changes(records):
    """Validate change records, collapsing identical duplicates."""
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = []
    index = {}
    for row in records:
        if not isinstance(row, dict):
            raise JournalError("invalid-change")
        change_id = row.get("id")
        component = row.get("component")
        units = row.get("units")
        if (not isinstance(change_id, str) or not change_id
                or not isinstance(component, str) or not component
                or type(units) is not int or units < 1):
            raise JournalError("invalid-change")
        depends_on = row.get("depends_on")
        if depends_on is None:
            depends_on = []
        dependencies = _ids(depends_on)
        change = {
            "id": change_id,
            "component": component,
            "units": units,
            "depends_on": set(dependencies),
        }
        if change_id in index:
            previous = changes[index[change_id]]
            if (previous["component"] != component
                    or previous["units"] != units
                    or previous["depends_on"] != change["depends_on"]):
                raise JournalError("conflicting-change")
            continue
        index[change_id] = len(changes)
        changes.append(change)
    return changes


def read_applied(request):
    """Return the persisted release journal supplied by the caller."""
    value = request.get("applied")
    if value is None:
        return set()
    return set(_ids(value))


def read_retain(request):
    """Return the rollback retain list, defaulting to empty.

    Only well-formed lists of change IDs are accepted; whether each ID is
    actually applied is the planner's concern.
    """
    value = request.get("retain")
    if value is None:
        return []
    return _ids(value, "invalid-retain")

