"""Validate release policy before computing actions."""

ENVIRONMENTS = {"staging", "production"}

# G1: every environment supports both actions. Restricted environments would be
# added here as a per-environment set, so planner never needs to know.
SUPPORTED_ACTIONS = {"staging": {"plan", "rollback"}, "production": {"plan", "rollback"}}


class PolicyError(ValueError):
    pass


def policy_gate(request):
    """Check environment, action and budget shape; return the raw budget.

    The budget is returned as-is and is deliberately NOT compared here: policy
    owns the shape, while the cap depends on replay/deduplication (journal) and
    does not apply to rollback at all, so the cap belongs to planner. Doing the
    cap here would force policy to know about journal state.
    """
    environment = request.get("environment")
    if not isinstance(environment, str) or environment not in ENVIRONMENTS:
        raise PolicyError("invalid-environment")
    action = request.get("action")
    if not isinstance(action, str) or action not in SUPPORTED_ACTIONS[environment]:
        raise PolicyError("unsupported-action")
    budget = request.get("budget")
    # `type(...) is int` rejects booleans: True is an int subclass but not a count.
    if type(budget) is not int or budget < 0:
        raise PolicyError("invalid-budget")
    return budget


def limit_for(request):
    """Backwards-compatible alias for callers written before G1."""
    return policy_gate(request)

