"""JSON transport for the release planner.

Transport only: read one JSON value from stdin, hand the already-parsed value to
planner, print one JSON object, always exit 0. No file, no network, and no
deployment is ever executed. Every domain decision belongs to planner (and its
collaborators); this module decides only whether the bytes were JSON at all.
"""
import json
import sys

from planner import plan


def _failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _shape(result):
    """Normalize a planner result to one of the two exact allowed shapes.

    The contract is exact: a success carries `actions` and `units`, a failure
    carries an empty `actions` and zero `units`, and no other keys leak out.
    A disallowed operation must never surface partial actions, so a failure is
    rebuilt from scratch rather than trusting its payload. Anything that does
    not match a known shape is reported as `invalid-request`, which keeps the
    four-key output invariant even if a collaborator misbehaves.
    """
    if not isinstance(result, dict):
        return _failure("invalid-request")
    if result.get("status") == "ok":
        actions = result.get("actions")
        units = result.get("units")
